<?php
namespace App\Http\Controllers;
use App\Services\AI\AiSettingsStore;use Illuminate\Http\Request;
class AdminAiSettingsController extends Controller
{
 public function edit(AiSettingsStore $store){abort_unless(auth()->user()?->hasRole('admin'),403);return view('admin.ai.settings',['settings'=>['provider'=>$store->get('provider',config('ai.provider','gemini')),'timeout'=>$store->get('timeout',config('ai.timeout',30)),'fallback_provider'=>$store->get('fallback_provider',config('ai.fallback_provider','gapgpt')),'fallback_model'=>$store->get('fallback_model',config('ai.fallback_model','gpt-4o-mini')),'fallback_endpoint'=>$store->get('fallback_endpoint',config('ai.fallback_endpoint','https://api.gapgpt.app/v1'))]]);}
 public function update(Request $request,AiSettingsStore $store){abort_unless(auth()->user()?->hasRole('admin'),403);$data=$request->validate(['provider'=>'required|in:gemini','gemini_key'=>'nullable|string|max:500','fallback_provider'=>'nullable|in:gapgpt','fallback_key'=>'nullable|string|max:500','fallback_endpoint'=>'nullable|url|max:500','fallback_model'=>'nullable|string|max:120','timeout'=>'required|integer|min:5|max:120']);$store->put('provider',$data['provider']);if(filled($data['gemini_key']))$store->put('key',$data['gemini_key'],true);if(array_key_exists('fallback_provider',$data))$store->put('fallback_provider',$data['fallback_provider']?:null);if(filled($data['fallback_key']))$store->put('fallback_key',$data['fallback_key'],true);if(filled($data['fallback_endpoint']))$store->put('fallback_endpoint',$data['fallback_endpoint']);if(filled($data['fallback_model']))$store->put('fallback_model',$data['fallback_model']);$store->put('timeout',(string)$data['timeout']);return back()->with('success','تنظیمات هوش مصنوعی با موفقیت ذخیره شد.');}
}
